// Package iconset is the server's copy of the icon catalogue (OpenSpec change
// icons-and-section-style, design D2): the icons a person can choose for projects
// and sections. names.json is generated by scripts/icons-sync.mjs from
// web/src/ui/icons/catalogue.json; a test fails when the two differ.
//
// Valid is the one check REST and MCP writes use for an icon name. Sync does not
// use it: an op from a newer client may carry a name this server does not know yet.
package iconset

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
)

//go:embed names.json
var raw []byte

// Entry is one catalogue icon.
type Entry struct {
	Name     string   `json:"name"`
	Category string   `json:"category"`
	Keywords []string `json:"keywords"`
}

var (
	entries []Entry
	byName  map[string]struct{}
)

func init() {
	if err := json.Unmarshal(raw, &entries); err != nil {
		panic("iconset: names.json: " + err.Error())
	}
	byName = make(map[string]struct{}, len(entries))
	for _, e := range entries {
		byName[e.Name] = struct{}{}
	}
}

// Valid reports whether name is an icon of the catalogue.
func Valid(name string) bool {
	_, ok := byName[name]
	return ok
}

// Entries returns every catalogue icon in catalogue order. The slice is a copy.
func Entries() []Entry {
	out := make([]Entry, len(entries))
	copy(out, entries)
	return out
}

// Rank orders a match: exact name, then name prefix, then name substring, then
// keyword, then category (design D2). A smaller rank is a better match; -1 is none.
func Rank(e Entry, query, categoryLabel string) int {
	q := strings.ToLower(strings.TrimSpace(query))
	if q == "" {
		return 0
	}
	switch {
	case e.Name == q:
		return 0
	case strings.HasPrefix(e.Name, q):
		return 1
	case strings.Contains(e.Name, q):
		return 2
	}
	for _, k := range e.Keywords {
		if strings.Contains(strings.ToLower(k), q) {
			return 3
		}
	}
	if strings.Contains(strings.ToLower(e.Category), q) || (categoryLabel != "" && strings.Contains(strings.ToLower(categoryLabel), q)) {
		return 4
	}
	return -1
}

// Search returns the icons matching query in the order of Rank, ties in catalogue
// order; an empty query returns every icon. The category is matched by its id (the
// server has no interface language).
func Search(query string) []Entry {
	type hit struct {
		e    Entry
		rank int
		i    int
	}
	var hits []hit
	for i, e := range entries {
		if r := Rank(e, query, ""); r >= 0 {
			hits = append(hits, hit{e, r, i})
		}
	}
	sort.SliceStable(hits, func(a, b int) bool {
		if hits[a].rank != hits[b].rank {
			return hits[a].rank < hits[b].rank
		}
		return hits[a].i < hits[b].i
	})
	out := make([]Entry, len(hits))
	for i, h := range hits {
		out[i] = h.e
	}
	return out
}
